package in.recallradar;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="finished_product") class FinishedProduct{@Id UUID id; UUID organizationId; String name; String sku; String unit; boolean active=true; Instant createdAt; protected FinishedProduct(){} FinishedProduct(UUID org,String name,String sku,String unit){id=UUID.randomUUID();organizationId=org;this.name=name;this.sku=sku;this.unit=unit;createdAt=Instant.now();}}
@Entity @Table(name="recipe") class Recipe{@Id UUID id; UUID organizationId; UUID productId; String name; BigDecimal yieldQuantity; String yieldUnit; boolean active=true; Instant createdAt; protected Recipe(){} Recipe(UUID org,UUID product,String name,BigDecimal yield,String unit){id=UUID.randomUUID();organizationId=org;productId=product;this.name=name;yieldQuantity=yield;yieldUnit=unit;createdAt=Instant.now();}}
@Entity @Table(name="recipe_ingredient") class RecipeIngredient{@Id UUID id; UUID recipeId; UUID ingredientId; BigDecimal quantity; String unit; protected RecipeIngredient(){} RecipeIngredient(UUID recipe,UUID ingredient,BigDecimal quantity,String unit){id=UUID.randomUUID();recipeId=recipe;ingredientId=ingredient;this.quantity=quantity;this.unit=unit;}}
@Entity @Table(name="production_batch") class ProductionBatch{@Id UUID id; UUID organizationId; UUID recipeId; UUID locationId; String batchNumber; BigDecimal outputQuantity; String outputUnit; Instant producedAt; String note; protected ProductionBatch(){} ProductionBatch(UUID org,UUID recipe,UUID location,String batch,BigDecimal output,String unit,String note){id=UUID.randomUUID();organizationId=org;recipeId=recipe;locationId=location;batchNumber=batch;outputQuantity=output;outputUnit=unit;this.note=note;producedAt=Instant.now();}}
@Entity @Table(name="production_consumption") class ProductionConsumption{@Id UUID id; UUID productionBatchId; UUID lotId; UUID locationId; BigDecimal quantity; String unit; protected ProductionConsumption(){} ProductionConsumption(UUID batch,UUID lot,UUID location,BigDecimal quantity,String unit){id=UUID.randomUUID();productionBatchId=batch;lotId=lot;locationId=location;this.quantity=quantity;this.unit=unit;}}
